def find_lca(parents: List[int], u: int, v: int) -> int:
    depth = [0] * len(parents)
    def dfs(node: int, d: int) -> None:
        depth[node] = d
        for child in parents[node]:
            dfs(child, d + 1)
    dfs(0, 0)

    if depth[u] > depth[v]:
        u, v = v, u

    for _ in range(depth[v] - depth[u]):
        v = parents[v]

    while u != v:
        u = parents[u]
        v = parents[v]

    return u

def is_path_black(edges: List[Tuple[int, int]], colors: List[bool], u: int, v: int, lca: int) -> bool:
    def dfs(node: int, target: int, visited: set) -> bool:
        if node == target:
            return True
        visited.add(node)
        for neighbor in edges[node]:
            if neighbor not in visited and dfs(neighbor, target, visited):
                return True
        return False

    path_u_to_lca = dfs(u, lca, set())
    path_v_to_lca = dfs(v, lca, set())

    for edge in edges[lca]:
        if edge != u and edge != v:
            if dfs(edge, u, set()) and dfs(edge, v, set()):
                return colors[edge]

    return path_u_to_lca and path_v_to_lca and colors[lca]

def count_valid_paintings(N: int, edges: List[Tuple[int, int]], M: int, restrictions: List[Tuple[int, int]]) -> int:
